import{_ as l,a0 as p,w as o,s as r,I as i,x as a,a1 as n,A as t,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"一个更好的视频码头 | LCTT x X-CMD","titleTemplate":false,"description":"一个更好的视频码头 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一个更好的视频码头 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一个更好的视频码头 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20210111 an even better video wharf","title":"一个更好的视频码头","tag":"202304","desc":""},"relativePath":"202304/20210111 an even better video wharf.md","filePath":"[post].md"}'),u={name:"202304/20210111 an even better video wharf.md"};function m(g,s,k,h,b,c){const e=p("Link");return o(),r("div",null,[s[20]||(s[20]=i("h1",{id:"一个更好的视频码头",tabindex:"-1"},[a("一个更好的视频码头 "),i("a",{class:"header-anchor",href:"#一个更好的视频码头","aria-label":"Permalink to “一个更好的视频码头”"},"​")],-1)),s[21]||(s[21]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/11/150233vzkt1tute4i4oemg.jpg",alt:""})],-1)),i("p",null,[s[2]||(s[2]=a("之前，",-1)),n(e,{href:"https://jao.io/blog/2021-01-09-embarking-videos.html"},{default:t(()=>[...s[0]||(s[0]=[a("我在写",-1)])]),_:1}),s[3]||(s[3]=a(" 有关 ",-1)),n(e,{href:"https://github.com/oantolin/embark"},{default:t(()=>[...s[1]||(s[1]=[a("embark",-1)])]),_:1}),s[4]||(s[4]=a(" 的内容，我的第一设备为启动远程视频流设计了一个新的 embark。embark 的作者 Omar Antolín Camarena 不仅阅读了这篇内容，还点评了一下我认为值得跟进的一些重大改进。",-1))]),s[22]||(s[22]=d(`<p>首先，你应该记得我们曾定义过一个检测视频 URL 的函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (defun jao-video-finder ()</span></span>
<span class="line"><span>      &quot;Check whether we&#39;re looking at a video URL.</span></span>
<span class="line"><span>    Return (video-url . &lt;URL&gt;) if so.&quot;</span></span>
<span class="line"><span>      (when-let ((url (thing-at-point-url-at-point)))</span></span>
<span class="line"><span>        (when (string-match-p jao-video-url-rx url)</span></span>
<span class="line"><span>          (cons &#39;video-url url))))</span></span></code></pre></div><p>当我们得到了一个非空的 <code>url</code> 值，即便它不是一个视频链接，但它仍然是一个确切的 URL，并且 embark 已有了一个 <code>url</code> 类别，所以我们可以借助默认的 URL 寻检器存储一个新的句法分析,语句如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (when-let ((url (thing-at-point-url-at-point)))</span></span>
<span class="line"><span>      (cons (if (string-match-p jao-video-url-rx url) &#39;video-url &#39;url) url))</span></span></code></pre></div><p>这里有一个潜在的缺点就是：我们重写了 embark 的寻检器，<code>embark-target-url-at-point</code>，所以我们可能更愿意保留后者。</p><p>实际上多亏了 embark 的 <em>目标转换器</em> 我们才能做成。我们可以在 <code>embark-transformers-alist</code> 中添加任意一个函数，应用于任何一个给定类别的目标，而 embark 会将其转换后的值应用于它的操作中。Omar 很贴切地把这个过程称为“目标的精化”;我们具体做法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (defun jao-refine-url-type (url)</span></span>
<span class="line"><span>      &quot;Refine type of URL in case it is a video.&quot;</span></span>
<span class="line"><span>      (cons (if (string-match-p jao-video-url-rx url) &#39;video-url &#39;url) url))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    (add-to-list &#39;embark-transformer-alist &#39;(url . jao-refine-url-type))</span></span></code></pre></div><p>通过这种策略，我们就不再需要 <code>jao-video-finder</code> 了，而且从概念上来说，我们的 <code>video-url</code> 应该被定义为一个精化操作而并非是一个目标 [脚注 1]。Omar 的第二个提议也与这个概念相契合：想必我们都希望所有关于 <code>url</code> 和我们的 <code>video-url</code> 的操作都是可用的，不是吗？ 唔，这就是为什么我们用来定义行为的 <code>embark-define-keymap</code> 的宏可以通过使用关键字 [脚注 2] <code>:parent</code> 继承其他键映射中已经定义的所有操作的原因：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (embark-define-keymap jao-video-url-map</span></span>
<span class="line"><span>      &quot;Actions on URLs pointing to remote video streams.&quot;</span></span>
<span class="line"><span>      :parent embark-url-map</span></span>
<span class="line"><span>      (&quot;p&quot; jao-play-video-url))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    (add-to-list &#39;embark-keymap-alist &#39;(video-url . jao-video-url-map))</span></span></code></pre></div><p>这种继承键映射的功能并非是 embark 的附属功能：vanilla Emacs 键映射通过标准函数 <code>set-keymap-parent</code> 已经搞定它了。你可以完全不用 <code>embark-define-keymap</code> 来定义 <code>jao-video-url-map</code>，工作原理是一样的。</p><p>这样，我们的代码就能够更短，特征更多：谢谢你，Omar！</p><p><strong>脚注 1</strong>：在某些情况下，保留 jao-video-finder 是有意义的，即，如果我们想要改变检测 URL 的功能的话。例如，我在使用 emacs-w3m 的时候，经常有一个 URL 作为文本属性储存了起来(实际文本是个链接文本)。要通过那里检索 URL，就需要调用 <code>w3m-anchor</code>，而用 <code>embark-target-url-at-point</code> 就会错过它。对于这种情况，我最终编写(并使用)<code>jao-video-finder</code> 将其通过下文定义:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (when-let ((url (or (w3m-anchor) (thing-at-point-url-at-point))))</span></span>
<span class="line"><span>      (cons (if (string-match-p jao-video-url-rx url) &#39;video-url &#39;url) url))</span></span></code></pre></div><p>另一种达成同件事情的方式（再次向 Omar 致敬）便是为 w3m 的锚点放置一个特定的巡检器（且继续使用 video-url 的转换器）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (defun jao-w3m-url-finder ()</span></span>
<span class="line"><span>      (when-let ((url (w3m-anchor)))</span></span>
<span class="line"><span>        (cons &#39;url url)))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    (add-to-list &#39;embark-target-finders #&#39;jao-w3m-url-finder)</span></span></code></pre></div><p>这种方法更加模块化，并且取决于你们的喜好，且更加巧妙。这些功能都很小巧并且两种方法之间并没有太大的差别，但是如果其中某一种继续加入更多寻检器的话，前一种方法用起来来反而会让一切变得更糟。</p><p><strong>脚注 2</strong>：在我最开始的例子中，我在视频地图中还添加了 <code>browse-url</code> 和 <code>browse-url-firefox</code>。前一个已不再重要，因为它已经在 <code>embark-url-map</code> 中出现过了，如果我们想让 <code>browse-url-firefox</code> 对 <em>所有</em> 的 URLs 可用,我们可以将其加入到 <code>embark-url-map</code> （谨记，embark 的键映射只是 Emacs 的键映射）。这是另一种扩展 embark 的简便方法。</p><p><em>（题图：MJ:emacs video geek wallpaper dark plain background Illustration）</em></p><hr>`,19)),i("p",null,[s[6]||(s[6]=a("via: ",-1)),n(e,{href:"https://jao.io/blog/an-even-better-video-wharf.html"},{default:t(()=>[...s[5]||(s[5]=[a("https://jao.io/blog/an-even-better-video-wharf.html",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("作者：",-1)),n(e,{href:"https://jao.io"},{default:t(()=>[...s[7]||(s[7]=[a("jao",-1)])]),_:1}),s[12]||(s[12]=a(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 译者：",-1)),n(e,{href:"https://github.com/Drwhooooo"},{default:t(()=>[...s[9]||(s[9]=[a("Drwhooooo",-1)])]),_:1}),s[14]||(s[14]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const C=l(u,[["render",m]]);export{w as __pageData,C as default};
